/// <summary>
/// Vendor Claim Process - Create journal and post. Used in Standard cost, Free item and excise duty variance claims
/// CB434_BasePriceVersion4StandardCosting, modified for FSD CB 434
/// Batch controller class extends SysOperationServiceController
/// </summary>
[
    SysOperationJournaledParametersAttribute(true)
]
public class METVendClaimJournalController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
    /// <summary>
    /// Standard Cost Vendor Claim process
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METVendClaimJournalService));
        this.parmMethodName(methodStr(METVendAutoGeneratePaymService, processOperation));
        this.parmDialogCaption(this.caption());
    }

/// <summary>
/// Caption of the batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:StandardCostVendorClaimProcess";
}

    /// <summary>
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METVendClaimJournalController controller;

        controller = new METVendClaimJournalController();
        controller.parmArgs(args);
        controller.startOperation();
    }

/// <summary>
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METVendClaimJournalController construct()
{
    return new METVendClaimJournalController();
}

/// <summary>
/// Control whether batch task should retry in case of SQL transient errors.
/// </summary>
/// <returns>true if task should be retried; otherwise, false.</returns>
public boolean isRetryable()
{
    return true;
}
